import { describe, it, expect } from "vitest";
import { basePremium, runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
    it.todo("newcomer with a cursed steel sword (enchantment 3) → premium 165 G");
  });

  describe("base premiums", () => {
    it.todo("sword → 100 G, amulet → 60 G, staff → 80 G, potion → 40 G");
    it.todo("2 runes → 50 G base premium");
    it.todo("3 runes → 60 G base premium (block applies)");
    it.todo("4 runes → 100 G base premium (block requires exactly 3)");
    it.todo("7 runes → 175 G base premium");
    it.todo("2 runes + 1 moonstone → 75 G base premium (different types, no block)");
    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
  });

  describe("premium modifiers", () => {
    it.todo("cursed sword + plain amulet, curse applies only to the sword's base → 210 G before policy modifiers and fee (236 G premium)");
    it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies (145 G)");
    it.todo("cursed sword with enchantment 5 → both surcharges apply (195 G)");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge (115 G); cursed → 165 G");
    it.todo("customer with exactly 2 years with MHPCO → loyalty discount applies (95 G for a plain sword)");
    it.todo("customer's second quote gets 15 % follow-up discount, first insurance still applies");
    it.todo("long-standing customer's second contract, cursed sword enchantment 7 → premium 160 G");
    it.todo("premium yielding 197.5 G is rounded up to 198 G");
  });

  describe("claim", () => {
    it.todo("regular steel sword enchantment 3, damage 500 G → payout 400 G, remaining cap 1600 G");
    it.todo("rune damage 200 G → payout 100 G");
    it.todo("steel sword enchantment 9, damage 1000 G → payout 400 G");
    it.todo("dragon-material sword enchantment 9, damage 1000 G → payout 400 G");
    it.todo("dragon-material sword exactly enchantment 8, damage 1000 G → payout 400 G");
    it.todo("dragon-material sword enchantment 5, damage 800 G → payout 700 G");
    it.todo("dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G, cap based on insurance sum 1600 G → remaining 2600 G");
    it.todo("cursed sword → cap 2000 G, premium modifiers do not raise the cap");
    it.todo("sword + 3 runes → insurance sum 1750 G, cap 3500 G");
    it.todo("two swords → cap 4000 G; two sword damages each with own deductible");
    it.todo("two successive 1500 G claims on a sword → 1400 G (cap 600 G), then 600 G (cap 0 G)");
    it.todo("payout yielding 350.5 G is rounded down to 350 G");
  });

  describe("errors", () => {
    it.todo("quote with unknown item type → throws");
    it.todo("claim for an item not part of the policy → throws");
    it.todo("claim with unknown item type → throws");
    it.todo("claim with more damages of a type than insured → throws");
    it.todo("claim with negative amount → throws");
  });

  describe("CLI", () => {
    it.todo("reads a scenario from stdin and writes results JSON to stdout");
    it.todo("exits non-zero with an error on stderr and no results on stdout for invalid input");
  });
});

