export type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };
export type QuoteStep = { op: "quote"; items: Item[] };
export type Scenario = { customer: { yearsWithMHPCO: number }; steps: QuoteStep[] };
export type Result = { premium: number } | { payout: number; remainingCap: number };

const PROCESSING_FEE = 5;

const COMPONENT_PREMIUM = 25;
const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: COMPONENT_PREMIUM,
  moonstone: COMPONENT_PREMIUM,
};

const itemBasePremium = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];

const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

const COMPONENT_TYPES = ["rune", "moonstone"];

const groupPremium = (type: string, count: number): number => {
  if (COMPONENT_TYPES.includes(type) && count === BLOCK_SIZE) return BLOCK_PREMIUM;
  return count * BASE_PREMIUM_BY_TYPE[type];
};

export const basePremium = (items: Item[]): number => {
  const countByType = new Map<string, number>();
  for (const item of items) countByType.set(item.type, (countByType.get(item.type) ?? 0) + 1);
  let total = 0;
  for (const [type, count] of countByType) total += groupPremium(type, count);
  return total;
};

const quotePremium = (items: Item[]): number => {
  if (items.length === 0) return PROCESSING_FEE;
  return basePremium(items) + 50 + 10 + PROCESSING_FEE;
};

export const runScenario = (scenario: Scenario): { results: Result[] } => ({
  results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })),
});

